#!/usr/bin/env sh
# fetch flibco.com (BE) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://transportdata.be/dataset/a6be5ac2-4c2d-4719-9317-40375d90ff62/resource/ba815be7-aa79-4780-9180-d9636bf9e2c6/download/crl-gtfs-v2.zip"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
